import fs from 'node:fs';import assert from 'node:assert/strict';import{createHash}from'node:crypto';import{generatePrivateKey,privateKeyToAccount}from'./enclave/node_modules/viem/_esm/accounts/index.js';
import https from 'node:https';import{Resolver}from'node:dns/promises';
const resolver=new Resolver();resolver.setServers(['1.1.1.1']);
async function publicFetch(url,options={}){const host=new URL(url).hostname;const ips=await resolver.resolve4(host);return new Promise((resolve,reject)=>{const req=https.request(url,{method:options.method||'GET',headers:options.headers,signal:options.signal,lookup:(_host,opt,cb)=>cb(null,opt.all?ips.map(address=>({address,family:4})):ips[0],4)},res=>{const chunks=[];res.on('data',b=>chunks.push(b));res.on('error',reject);res.on('end',()=>resolve(new Response(Buffer.concat(chunks),{status:res.statusCode,headers:res.headers})));});req.on('error',reject);req.end(options.body);});}
const origin='https://7ae476a3.app.enclave.host',service='0x7ae476a3a1e4b0b144248075ff6656a0a10c3ae4cea8b6e4ad2b59dd8989ce33';
const get=async path=>{const r=await publicFetch(origin+path,{signal:AbortSignal.timeout(30000)});assert.equal(r.status,200);return r;};
const before=await(await get('/api/status')).json();assert.ok(['ready','hashing','listing'].includes(before.state));assert.equal(before.missing.length,0);
const account=privateKeyToAccount(generatePrivateKey()),address=account.address.toLowerCase(),expiry=Math.floor(Date.now()/1000)+300;
const body=JSON.stringify({test:'enclave-direct-wallet-upload',release:'1.0.17',storageCutover:'minipc',at:new Date().toISOString()});const sha=createHash('sha256').update(body).digest('hex');
const message=s=>`enclave-storage-upload:v1\nchainId:8453\nservice:${s}\nmethod:POST\npath:/add-json\naddress:${address}\nsha256:${sha}\nbytes:${Buffer.byteLength(body)}\nexpiry:${expiry}`;
async function upload(audience){const signature=await account.signMessage({message:message(audience)});return publicFetch(origin+'/add-json',{method:'POST',headers:{'content-type':'application/json','x-upload-address':address,'x-upload-expiry':String(expiry),'x-upload-sha256':sha,'x-upload-signature':signature},body,signal:AbortSignal.timeout(240000)});}
const bad=await upload('0x'+'ab'.repeat(32));assert.equal(bad.status,403);assert.match(await bad.text(),/invalid wallet upload signature/);
const good=await upload(service);const result=await good.json();assert.equal(good.status,200,JSON.stringify(result));assert.ok(result.cid);
const served=await(await get('/ipfs/'+result.cid)).text();assert.equal(served,body);
const report={verifiedAt:new Date().toISOString(),status:'passed',directWalletUpload:true,dnsResolver:'1.1.1.1 (local resolver retained a negative cache entry)',tlsCertificateValidation:true,nanUploadTokenUsed:false,wrongDeploymentSignatureRejected:true,uploadedCid:result.cid,bytes:Buffer.byteLength(body),roundTripExact:true,before:{state:before.state,uptime:before.uptime,files:before.files,rootCid:before.rootCid,error:before.error},notes:['A fresh ephemeral test wallet signed only a public smoke-test JSON upload; no user-wallet key or Nan-issued upload token was used.','This proves direct upload authorization and live storage round trip; Sia/indexd runs on minipc; Nan currently forwards the old DNS endpoint while the DNS cutover remains pending.']};fs.writeFileSync('outputs/storage-cutover-wallet-verification.json',JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(report,null,2));
